('DS-039', 'Mapa de Violencia de Género — CABA (2021–2024)', 'Gobierno de la Ciudad de Buenos Aires (GCBA)', 'ARG', 2024, 'Violencia de género urbana · llamadas 911 · dispositivos de pánico · tobilleras', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'Menos de 2 años — frecuencia vigente', 'Distribución geográfica (comunas CABA)', 'CSV', 'https://data.buenosaires.gob.ar/dataset/mapa-violencia-de-genero', 'Datos de violencia de género por comuna: llamadas 911, denuncias, consignas policiales, dispositivos de pánico, tobilleras y Centros Integrales de la Mujer. Cobertura exclusiva CABA.'),
('DS-040', 'Encuesta Nacional de Uso del Tiempo 2021 (ENUT)', 'INDEC Argentina', 'ARG', 2022, 'Uso del tiempo por sexo · trabajo no remunerado · cuidados · TIC', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'Más de 2 años — contribuye a Parcial', 'Distribución geográfica (regional)', 'TXT · PDF', 'https://www.indec.gob.ar/indec/web/Nivel4-Tema-4-31-117', 'Mujeres dedican 5:59 hs/día al trabajo no remunerado vs 2:45 hs los varones. Incluye módulo de uso de TIC por sexo. Cobertura nacional por región. Sin desagregación provincial.'),
('DS-041', 'Datos de Género en Ciencia y Tecnología — MINCyT / SICYTAR', 'Ministerio de Ciencia, Tecnología e Innovación (MINCyT)', 'ARG', 2024, 'Investigadoras por categoría · disciplina · institución · brecha de género en CyT', 'Ag. Tecnológica · Ag. Datos · Ag. Género', 'Menos de 2 años — frecuencia vigente', 'Solo totales nacionales (por organismo y disciplina)', 'Portal de datos (descarga)', 'https://datasets.datos.mincyt.gob.ar/dataset?groups=genero', '53% de CONICET son mujeres, pero solo 24.5% en categoría superior. Brecha de género en dirección de proyectos y publicaciones. Sin desagregación geográfica ni institucional completa.'),
('DS-042', 'Infraestructura de salud, cuidados y géneros - Equipamiento sanitario', 'Dirección Nacional de Transparencia. Ministerio de Obras Públicas', 'ARG', 2023, 'Cuidado. cuidades
INSERT INTO normativas VALUES
('NM-001', 'CEDAW — Convención sobre la Eliminación de Todas las Formas de Discriminación contra la Mujer', 'ONU / Asamblea General', 'Convenio internacional', 'Internacional', 1979, 'Artículos 1–16 · Rec. General 19 · Rec. General 38', 'Los Estados deben recopilar estadísticas desagregadas por sexo en todas las esferas cubiertas. La Rec. 19 obliga a producir datos sobre violencia de género. La Rec. 38 exige datos sobre trata y migración con perspectiva de género.', 'Ag. Género · Ag. Datos', 'https://www.ohchr.org/es/instruments-mechanisms/instruments/convention-elimination-all-forms-discrimination-against-women', 'Instrumento vinculante universalmente reconocido. Ratificado por todos los países de ALyC. Fundamento jurídico central del sistema de datos de género.'),
('NM-002', 'Convención de Belém do Pará — Prevención, Sanción y Erradicación de Violencia contra la Mujer', 'OEA / CIM', 'Convenio regional', 'ALyC', 1994, 'Artículos 7–9 · MESECVI 2024', 'Los Estados deben producir y publicar datos estadísticos sobre violencia contra las mujeres, incluyendo feminicidio, violencia sexual y doméstica, con desagregación geográfica y temporal.', 'Ag. Género · Ag. Datos', 'https://www.oas.org/es/mesecvi/convencion.asp', 'Primer tratado regional vinculante sobre violencia de género. Mecanismo de seguimiento: MESECVI. Obliga a los 32 Estados Parte a producir estadísticas desagregadas de violencia.'),
('NM-003', 'ODS 5 — Objetivo de Desarrollo Sostenible: Igualdad de Género', 'ONU / DESA', 'ODS / Meta', 'Internacional', 2015, 'Metas 5.1 · 5.2 · 5.3 · 5.5 · 5.6 · 5.b', 'Los Estados deben monitorear indicadores desagregados por sexo. Meta 5.2: datos sobre violencia. Meta 5.5: participación política. Meta 5.b: uso de TIC por mujeres.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://sdgs.un.org/goals/goal5', 'Marco global de seguimiento. 17 indicadores bajo ODS 5. Gender Snapshot 2024: el 40% de indicadores no tiene datos suficientes a nivel global.'),
('NM-004', 'MESECVI — Informe Hemisférico sobre Violencia Sexual y Embarazo Infantil', 'OEA / MESECVI', 'Recomendación regional', 'ALyC', 2016, 'Recomendaciones 10 y 11 · Acuerdo 10 MESECVI/CEVI/doc.237', 'Los Estados deben registrar y publicar datos sobre embarazo en niñas y adolescentes producto de violencia sexual, con desagregación por edad, territorio y causa.', 'Ag. Género · Ag. Datos', 'https://www.oas.org/es/mesecvi/docs/MESECVI-EmbarazoInfantil-ES.pdf', 'Informe técnico del Comité de Expertas MESECVI. Clave para el monitoreo de NOM-046 en México y normas equivalentes en la región.'),
('NM-005', 'Agenda Regional de Género — Consenso de Montevideo + Compromiso de Buenos Aires', 'CEPAL / CRF', 'Plan de acción regional', 'ALyC', 2013, 'Medidas 1–6 Autonomía física · Medida 15 · Acuerdo BsAs 2022', 'Los Estados de ALyC se comprometen a producir estadísticas de género con perspectiva interseccional, incluyendo datos de mujeres indígenas, afrodescendientes y rurales.', 'Ag. Género · Ag. Datos', 'https://oig.cepal.org/es/acuerdos', 'Agenda intergubernamental más progresista de la región. Consenso de Montevideo (2013) + Compromiso de Buenos Aires (2022).'),
('NM-006', 'OHCHR — Guidance Note on Human Rights-Based Approach to Data (HRBA to Data)', 'OHCHR / ONU', 'Recomendación técnica', 'Internacional', 2018, 'Principios 1–6 · Sección III · Sección IV', 'Los sistemas de datos deben desagregar por grupos en situación de vulnerabilidad. Los datos deben usarse para rendir cuentas sobre obligaciones estatales de DDHH.', 'Ag. Datos · Ag. Género', 'https://www.ohchr.org/sites/default/files/Documents/Issues/HRIndicators/GuidanceNoteonApproachtoData_SP.pdf', 'Marco técnico central de Infra.Coop. Establece principios AAAQ aplicados a datos de DDHH.'),
('NM-007', 'Lineamientos Interamericanos para la Igualdad de Género — OEA/CIM', 'OEA / CIM', 'Lineamiento regional', 'ALyC', 2019, 'Eje 3: Datos · Eje 5: Tecnología', 'Los Estados deben garantizar la producción de estadísticas desagregadas por género en todos los sectores de política pública. Se requiere incorporar perspectiva de género en sistemas de información y tecnología.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://www.oas.org/en/cim/docs/LineamientosIgualdadGeneroBien-ES.pdf', 'Conecta derechos de las mujeres con desarrollo tecnológico y datos. Clave para el encuadre de Infra.Coop en la agenda interamericana.'),
('NM-008', 'Pacto Digital Global — ONU 2024 (Sección: datos inclusivos)', 'ONU / DESA', 'Acuerdo intergubernamental', 'Internacional', 2024, 'Principio de inclusión · Párrafos 15–23', 'Los sistemas de IA deben diseñarse para no reproducir sesgos de género. Los Estados deben publicar datos desagregados sobre brecha digital de género.', 'Ag. Tecnológica · Ag. Datos · Ag. Género', 'https://www.un.org/en/summit-of-the-future/global-digital-compact', 'Primer acuerdo intergubernamental sobre gobernanza digital de datos. Aprobado en la Cumbre del Futuro (septiembre 2024).'),
('NM-009', 'Marco de Copenhague sobre Datos Ciudadanos (BG-4c-CGD Framework)', 'Global Partnership for Sustainable Development Data', 'Marco técnico', 'Internacional', 2021, 'Principio BG-4c · Sección CGD', 'Los datos generados por la ciudadanía deben integrarse en ecosistemas estadísticos nacionales con gobernanza participativa y no extractivista.', 'Ag. Datos · Ag. Tecnológica · Ag. Género', 'https://www.data4sdgs.org/resources/call-action-citizen-generated-data', 'Marco central de la gobernanza cooperativa de Infra.Coop. Fundamenta la producción de datos ciudadanos.'),
('NM-010', 'Participation for Transformation — Framework for Gender Data (PARIS21)', 'PARIS21 / ONU', 'Marco técnico', 'Internacional', 2023, 'Principios 1–5 · Módulo Género', 'La producción de datos de género debe basarse en la participación activa de mujeres y organizaciones feministas en el diseño estadístico.', 'Ag. Datos · Ag. Género', 'https://paris21.org/gender-data-framework', 'Marco desarrollado por PARIS21 para transformar la producción de datos de género. Complemento del Marco de Copenhague.'),
('NM-011', 'Declaración y Plataforma de Acción de Beijing — 30 años (Beijing +30) 2025', 'ONU Mujeres / CSW', 'Declaración internacional', 'Internacional', 1995, 'Área J (Mujeres y los medios) · Área L (Niña) · Revisión 2025', 'Los Estados deben recopilar y analizar datos desglosados por sexo y edad. La revisión Beijing+30 (2025) refuerza la obligación de datos en el contexto digital.', 'Ag. Género · Ag. Datos', 'https://www.unwomen.org/es/how-we-work/intergovernmentally/beijing-conference', 'Marco fundacional adoptado por 189 gobiernos (1995). La revisión Beijing+30 añade dimensión tecnológica y de datos.'),
('NM-012', 'Consenso de Montevideo sobre Población y Desarrollo (CPID)', 'CEPAL / CELADE', 'Acuerdo regional', 'ALyC', 2013, 'Medidas 42–50 · Capítulo D (Acceso universal a SSR)', 'Los Estados deben producir y publicar datos sobre acceso a salud sexual y reproductiva con desagregación territorial.', 'Ag. Género · Ag. Datos', 'https://repositorio.cepal.org/handle/11362/21835', 'Acordado en Montevideo (2013). Revisado en CPID+25 (Nairobi, 2019). Los ''tres ceros'': cero muertes maternas evitables, cero necesidades insatisfechas, cero violencia de género.'),
('NM-013', 'ODS 3.1 — Mortalidad materna y atención calificada del parto', 'ONU / DESA', 'ODS / Meta', 'Internacional', 2015, 'Meta 3.1 · Indicador 3.1.1 · Indicador 3.1.2', 'Los Estados deben producir datos de mortalidad materna desagregados por causas directas e indirectas. El indicador 3.1.2 requiere desagregación territorial.', 'Ag. Género · Ag. Datos', 'https://sdgs.un.org/goals/goal3', 'Meta vinculada a NOM-007 en México. Sin datos desagregados por municipio y ruralidad, es imposible monitorear el cumplimiento.'),
('NM-014', 'Recomendación General CEDAW N°24 — Salud', 'ONU / Comité CEDAW', 'Recomendación', 'Internacional', 1999, 'Párrafos 1–27 · Artículo 12', 'Los Estados deben publicar datos que permitan monitorear la equidad territorial en el acceso a servicios de salud reproductiva.', 'Ag. Género · Ag. Datos', 'https://www.ohchr.org/en/documents/general-comments-and-recommendations/general-recommendation-no24-women-and-health', 'Recomendación vinculante del Comité CEDAW. Clave para la brecha de geolocalización de servicios identificada en el motor de brechas.'),
('NM-015', 'Agenda de Cooperación Digital ONU — Global Digital Compact (GDC) Objetivos y Metas', 'ONU / DESA / OICT', 'Acuerdo intergubernamental', 'Internacional', 2024, 'Objetivo 1B · Objetivo 4 · Meta sobre brecha digital de género', 'Los Estados deben monitorear y publicar datos sobre la brecha digital de género (acceso, uso, habilidades). Promover arquitecturas de datos inclusivas.', 'Ag. Tecnológica · Ag. Datos', 'https://www.un.org/techenvoy/global-digital-compact', 'Primer acuerdo global sobre gobernanza de datos e IA. Establece principios de inclusión y gobernanza participativa.'),
('NM-016', 'LGAMVLV — Ley General de Acceso de las Mujeres a una Vida Libre de Violencia (con reformas 2019–2026)', 'Congreso de la Unión — México', 'Ley General Federal', 'México', 2007, 'Arts. 6–20 Sexies · Cap. IV Ter (violencia digital) · Arts. 36–38 (sistema estadístico)', 'El SNIEG debe producir estadísticas anuales sobre todas las modalidades de violencia. La reforma 2021 obliga a registrar y reportar casos de violencia digital y mediática. El SESNSP debe publicar datos de feminicidio y violencia familiar con apertura municipal.', 'Ag. Género · Ag. Datos', 'https://www.diputados.gob.mx/LeyesBiblio/ref/lgamvlv.htm', 'Marco jurídico fundamental del sistema mexicano. 26 reformas desde 2007. La Reforma 16 (01/06/2021) incorporó la violencia digital y mediática. Última reforma: Decreto 26 (15/01/2026).'),
('NM-017', 'Ley Olimpia — Decreto que reforma CPF y LGAMVLV (violencia digital federal)', 'Congreso de la Unión — México', 'Reforma a Ley Federal', 'México', 2021, 'Arts. 199 Octies, 199 Nonies, 199 Decies del CPF · Art. 20 Quáter LGAMVLV', 'Tipifica como delito la difusión no consensuada de contenido íntimo (3-6 años). Incluye deepfakes (199 Nonies) y agravantes (199 Decies). Los ministerios públicos deben registrar y reportar estas carpetas de investigación.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://dof.gob.mx/nota_detalle.php?codigo=5619905&fecha=01/06/2021', 'Primera ley federal sobre violencia digital. Los 32 estados tienen reformas equivalentes. Más de 9,000 carpetas de investigación abiertas desde su vigencia.'),
('NM-018', 'NOM-046-SSA2-2005 — Violencia familiar, sexual y contra las mujeres: criterios para la atención médica', 'Secretaría de Salud México', 'Norma Oficial Mexicana', 'México', 2005, 'Numerales 5.5, 5.7, 8.4, 8.5 (registro y reporte)', 'Las unidades de salud deben registrar todos los casos de violencia detectados con variables específicas (tipo de violencia, relación con agresor, ámbito). El DGIS debe consolidar estas estadísticas en el registro de lesiones y causas de violencia.', 'Ag. Género · Ag. Datos', 'https://www.dof.gob.mx/nota_detalle.php?codigo=5430957&fecha=24/03/2016', 'Norma vinculante para todos los servicios de salud. Incluye anticoncepción de emergencia e ILE para víctimas de violación. Sin actualización para violencia digital desde 2016.'),
('NM-019', 'Ley Ingrid — Reforma al CPF sobre difusión de imágenes de víctimas', 'Congreso de la Unión — México', 'Reforma al Código Penal Federal', 'México', 2023, 'Art. 225 bis CPF · Art. 20 Septies LGAMVLV', 'Penaliza la difusión de imágenes de víctimas de delitos por servidores públicos (6-10 años). Obliga a registrar como agravante la difusión de material de investigación. 11+ estados tienen leyes equivalentes.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://ordenjuridico.gob.mx/violenciagenero/LEY%20INGRID.pdf', 'Aprobada por Senado el 12/09/2023. Nombrada en memoria de Ingrid Escamilla. Complementa la Ley Olimpia en el ámbito de protección de datos de víctimas.'),
('NM-020', 'LOIPEVM — Ley Orgánica Integral para Prevenir y Erradicar la Violencia contra las Mujeres', 'Asamblea Nacional Ecuador', 'Ley Orgánica', 'Ecuador', 2018, 'Arts. 10–16 (tipos de violencia) · Art. 12 num. 7 (ámbito mediático/digital) · Arts. 40–50 (sistema de información)', 'El Sistema Nacional de Información establece el Registro Único de Violencia (RUV) con datos de casos, victimarios, tipos de violencia e instituciones intervinientes. Incluye violencia en ámbito mediático y cibernético como modalidad reconocida.', 'Ag. Género · Ag. Datos', 'https://www.igualdad.gob.ec/wp-content/uploads/downloads/2018/05/ley_prevenir_y_erradicar_violencia_mujeres.pdf', 'Ley marco del sistema ecuatoriano contra la violencia de género. R.O. No. 175 (05/02/2018). Integra 22 instituciones del Estado. En proceso de reforma (diciembre 2025) para incorporar violencia digital explícita.'),
('NM-021', 'Reforma COIP 2021 — Ley Orgánica Reformatoria para Prevenir y Combatir la Violencia Sexual Digital', 'Asamblea Nacional Ecuador', 'Ley Orgánica Reformatoria', 'Ecuador', 2021, 'Art. 154 (hostigamiento digital) · Art. 166 (acoso sexual) · Art. 173 (grooming) · Art. 178 (violación a la intimidad)', 'Introduce 10 nuevos delitos de violencia sexual digital. Obliga al INEC y Fiscalía a desagregar las estadísticas de delitos digitales por sexo. El hostigamiento digital (Art. 154) y grooming (Art. 173) deben registrarse como categorías específicas.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://www.registroficial.gob.ec/index.php/registro-oficial-web/publicaciones/suplementos/item/16109-suplemento-ro-no-526-del-03-septiembre-2021', 'Reforma del 30/08/2021 (R.O. Suplemento No. 526). Equivalente funcional de la Ley Olimpia mexicana. Vacío: no hay tipo penal autónomo de pornovenganza ni mecanismos de retiro de contenido.'),
('NM-022', 'Ley Orgánica de Protección de Datos Personales (LOPDP) Ecuador', 'Asamblea Nacional Ecuador', 'Ley Orgánica', 'Ecuador', 2021, 'Arts. 4, 16 (datos sensibles: género, orientación sexual) · Art. 20 (decisiones automatizadas) · Art. 44 (Superintendencia)', 'Los datos sobre identidad de género y orientación sexual son datos sensibles con protección reforzada. Prohíbe decisiones basadas exclusivamente en valoraciones automatizadas. La Superintendencia puede sancionar usos de IA discriminatorios por género.', 'Ag. Tecnológica · Ag. Datos', 'https://www.gob.ec/regulaciones/ley-organica-proteccion-datos-personales', 'R.O. Suplemento No. 459 (26/05/2021). Primera ley integral de protección de datos de Ecuador. Superintendencia operativa desde agosto 2024. Relevante para violencia digital y uso de IA.'),
('NM-023', 'PLANVIG — Plan Nacional para Prevenir y Erradicar la Violencia de Género 2020–2025', 'Ministerio de la Mujer y DDHH Ecuador / Sistema LOIPEVM', 'Plan Nacional', 'Ecuador', 2020, 'Eje 1 (prevención) · Eje 3 (atención) · Eje 5 (información y datos) · Eje 6 (tecnología)', 'El plan establece metas de registro estadístico de violencia de género con desagregación por tipo, provincia, cantón, pueblo/nacionalidad y ámbito (incluyendo mediático/digital). El RUV debe actualizarse trimestralmente.', 'Ag. Género · Ag. Datos', 'https://www.planificacion.gob.ec/planifica-ecuador-presento-el-informe-de-evaluacion-al-plan-nacional-para-la-erradicacion-de-la-violencia-de-genero/', 'Sucesor del Plan 2007–2017. Articulado con el sistema LOIPEVM de 22 instituciones. Incluye dimensiones de violencia digital y mediática como parte del eje de información.'),
('NM-024', 'Ley 26.485 reformada por Ley Olimpia Argentina (27.736) — Violencia digital y telemática', 'Congreso de la Nación Argentina', 'Ley Nacional', 'Argentina', 2023, 'Art. 6 inc. i (violencia digital) · Arts. 26, 29 (medidas de protección digital) · Art. 37 bis (plataformas)', 'Define violencia digital como conductas contra mujeres basadas en género mediante TICs. Las plataformas deben remover contenido denunciado en 48 hs. Las pericias informáticas son gratuitas para víctimas. El SICVG debe registrar casos de violencia digital.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/390000-394999/391774/norma.htm', 'Ley 27.736 (B.O. 23/10/2023). Primera ley Olimpia de Argentina. Define 9 tipos específicos de violencia digital. Vacío: sin tipificación penal (Ley Belén pendiente).'),
('NM-025', 'Ley Micaela (27.499) — Capacitación en género y violencia para función pública', 'Congreso de la Nación Argentina', 'Ley Nacional', 'Argentina', 2019, 'Arts. 1–8 · Decreto Reglamentario 139/2020', 'El INAM debe producir y publicar estadísticas sobre implementación de la ley: personas capacitadas, organismos, horas. La capacitación incluye violencia digital y nuevas modalidades.', 'Ag. Género · Ag. Datos', 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/315000-319999/318666/norma.htm', 'B.O. 10/01/2019. Obliga a los tres poderes del Estado. La negativa constituye falta grave. Aplicación en MEX (2021) y ECU (proceso 2023) por influencia.'),
('NM-026', 'Ley Grooming (26.904) + Ley Mica Ortega (27.590) — Prevención del grooming', 'Congreso de la Nación Argentina', 'Ley Nacional', 'Argentina', 2020, 'Art. 131 CP (grooming) · Arts. 1–15 Ley 27.590 (Observatorio, campañas, capacitación)', 'El Observatorio Nacional debe producir estadísticas anuales sobre casos de grooming desagregadas por sexo, edad, plataforma y modalidad. 8 de cada 10 víctimas son mujeres.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/345000-349999/345231/norma.htm', 'Ley 27.590 reglamentada por Decreto 407/2022. Único instrumento nacional específico sobre prevención de violencia sexual digital contra NNyA. La Línea 137 registra estos casos.'),
('NM-027', 'Plan Nacional de Acción contra las Violencias por Motivos de Género (PNA 2022–2024)', 'Ministerio de las Mujeres, Géneros y Diversidad', 'Plan Nacional', 'Argentina', 2022, 'Eje 1 (prevención) · Eje 2 (asistencia) · Eje 3 (protección y justicia) · Eje 4 (gestión de información — SICVG)', 'El SICVG debe integrar datos de Línea 144, OVD, Línea 137, hospitales y poder judicial en un sistema de información único. Incluye indicadores de violencia digital. El PNA 2020-2022 y 2022-2024 ya no tiene continuidad por disolución del MMGyD.', 'Ag. Género · Ag. Datos', 'https://www.argentina.gob.ar/generos/plan-nacional-de-accion-contra-las-violencias-por-motivos-de-genero-2022-2024', '100 acciones de 20 ministerios. Con la disolución del MMGyD (diciembre 2023), no existe PNA 2024-2026. Discontinuidad institucional crítica.'),
('NM-028', 'Convenio 190 OIT — Violencia y Acoso en el Trabajo', 'OIT / Conferencia Internacional del Trabajo', 'Convenio Internacional vinculante', 'Internacional (MEX · ECU · ARG)', 2019, 'Arts. 1–19 · Recomendación 206', 'Los Estados parte deben recopilar datos sobre incidencia de violencia y acoso en el trabajo desagregados por sexo. Incluye acoso mediante TICs en contextos laborales. Los empleadores deben registrar incidentes.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://c190.lim.ilo.org/?lang=en', 'ARG: Ley 27.580 (ratificado 4° en el mundo, en vigor 23/02/2022). ECU: ratificado 19/05/2021. MEX: en vigor desde 06/07/2023. Primer tratado internacional que cubre comunicaciones digitales como ámbito de violencia.'),
('NM-029', 'Recomendación General CEDAW N°35 (2017) — Actualización de la RG 19 sobre violencia de género', 'ONU / Comité CEDAW', 'Recomendación General', 'Internacional', 2017, 'CEDAW/C/GC/35 · párrs. 20, 26, 29', 'La violencia de género se extiende a todos los espacios, incluyendo entornos digitales (párr. 20). Los Estados deben producir datos sobre violencia en línea desagregados por tipo de plataforma y modalidad. Reconoce la violencia de género como principio de derecho consuetudinario.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://www.ohchr.org/es/treaty-bodies/cedaw/general-recommendations', 'Actualiza la histórica RG 19 de 1992. Primer instrumento CEDAW que reconoce explícitamente los entornos digitales como ámbito de violencia de género.'),
('NM-030', 'Informe A/HRC/38/47 — Violencia en línea contra mujeres y niñas (Relatora Especial ONU)', 'Consejo de DDHH ONU', 'Informe temático del CDH', 'Internacional', 2018, 'Sección III (tipología) · Sección V (obligaciones estatales) · Sección VI (recomendaciones)', 'Los Estados deben producir datos desagregados sobre violencia en línea (ciberacoso, doxing, distribución no consensuada de imágenes, trolling). Plataformas deben reportar estos casos. Las leyes nacionales deben tipificar estas conductas.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://www.ohchr.org/en/documents/thematic-reports/ahrc3847-report-special-rapporteur-violence-against-women-its-causes-and', 'Documento fundacional de referencia sobre violencia digital de género. MEX y ECU copatrocinaron la Resolución A/HRC/RES/56/19 (2024) solicitando estudio actualizado.'),
('NM-031', 'Ley Modelo MESECVI sobre Violencia Digital contra las Mujeres (2025)', 'OEA / MESECVI', 'Ley Modelo (orientativa)', 'ALyC', 2025, 'Títulos I–V · Arts. sobre tipificación · obligaciones de plataformas · datos y estadísticas', 'Los Estados deben establecer registros específicos de violencia digital desagregados por modalidad (ciberacoso, sextorsión, deepfakes, difusión no consentida). Las plataformas deben proveer datos para fines estadísticos. El 73% de las mujeres ha experimentado violencia en línea.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://belemdopara.org/violencia-digital-contra-las-mujeres-por-razones-de-genero/', 'Primer estándar continental sobre violencia digital. Buenos Aires fue primera sede de consultas (noviembre 2024). Inspirada en la Ley Olimpia mexicana. Resolución ONU de noviembre 2024 (170 votos a favor, 1 en contra: Argentina).'),
('NM-032', 'Compromisos de Santiago (2020) y Tlatelolco (2025) — Conferencia Regional sobre la Mujer CEPAL', 'CEPAL / CRF', 'Acuerdo regional intergubernamental', 'ALyC', 2020, 'Compromiso de Santiago: acuerdos 1–10 (violencia) · acuerdos 15–20 (tecnología) · acuerdo 35 (datos) · Compromiso de Tlatelolco 2025', 'Los Estados se comprometen a producir estadísticas de violencia digital de género y brecha digital con perspectiva interseccional. El OIG de CEPAL debe incorporar indicadores de violencia tecnológica.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://conferenciamujer.cepal.org/14/es/documentos/compromiso-santiago', 'XIV Conferencia Regional (enero 2020): 48 acuerdos. XVI Conferencia (2025, Tlatelolco): incorpora nuevas formas de violencia digital. MEX, ECU y ARG son signatarios.'),
('NM-033', 'Principios de Yogyakarta +10 (2017) — Principio 36: Derecho a disfrutar DDHH en entornos TIC', 'Expertos independientes de DDHH', 'Principios / Soft law', 'Internacional', 2017, 'Principio 36 · Principio 6 (vida) · Principio 9 (trato inhumano)', 'Los Estados deben garantizar que personas LGBTIQ+ no sean objeto de violencia digital por razón de orientación sexual o identidad de género. Los datos sobre esta violencia deben producirse y publicarse desagregados.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://yogyakartaprinciples.org/principles-sp/', 'Los YP+10 (2017) añadieron 9 principios a los 29 originales (2006). Utilizados por la Corte IDH en OC-24/17. Relevantes para monitoreo de violencia digital contra personas trans y LGBTIQ+.'),
('NM-034', 'Marco UIT/ITU y Alianza EQUALS — Brecha digital de género', 'Unión Internacional de Telecomunicaciones (UIT)', 'Resolución / Alianza internacional', 'Internacional', 2017, 'Resolución 70 UIT (género) · Manual de Transversalización de Género 2023 · Alianza EQUALS', 'Los Estados miembros deben recopilar y publicar datos de acceso y uso de TICs desagregados por sexo. El Manual 2023 establece 35 indicadores de género para políticas digitales nacionales.', 'Ag. Tecnológica · Ag. Datos · Ag. Género', 'https://www.itu.int/women-and-girls/women-in-ict/handbook-on-mainstreaming-gender-in-digital-policies/', 'Primera guía mundial para transversalizar género en políticas digitales. MEX, ECU y ARG son miembros de la UIT. La Alianza EQUALS tiene 100+ socios en 115 países.'),
('NM-035', 'Resolución ONU A/C.3/79 — Eliminación de la violencia contra mujeres y niñas en entornos digitales', 'Asamblea General ONU', 'Resolución intergubernamental', 'Internacional', 2024, 'Párrs. 1–15 (tipificación) · párrs. 16–22 (datos y estadísticas) · párr. 30 (plataformas)', 'Los Estados deben producir datos sobre violencia digital desagregados por modalidad, plataforma y perfil de víctima. Las plataformas tecnológicas deben cooperar con estadísticas nacionales. Esta es la primera resolución específica de la ONU sobre este tema.', 'Ag. Género · Ag. Datos · Ag. Tecnológica', 'https://www.unwomen.org/es/noticias-y-eventos/noticias/2024/11', 'Aprobada en noviembre 2024 con 170 votos a favor. Notable: Argentina votó EN CONTRA, único país en hacerlo. MEX y ECU votaron a favor. Constituye un hito normativo para la región.'),
('NM-036', 'Declaración de Beijing y Plataforma de Acción (Beijing+30, 2025)', 'ONU / ONU Mujeres — IV Conferencia Mundial sobre la Mujer', 'Declaración y plan de acción internacional', 'Internacional', 1995, 'Área estratégica J (mujer y medios) · Área B (educación) · Área F (economía) · revisión Beijing+30 2025', 'Los Estados deben recopilar, analizar y difundir estadísticas desagregadas por sexo. El área J exige incorporar perspectiva de género en TIC. La revisión 2025 incorpora compromisos sobre brecha digital y violencia tecnológica.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.un.org/womenwatch/daw/beijing/pdf/BDPfA%20S.pdf', 'Adoptada en 1995 por 189 gobiernos. Es la hoja de ruta global más completa para los derechos de las mujeres. Su área J es el primer instrumento internacional que exige incorporar perspectiva de género en TIC y medios. En 2025, su 30.º aniversario (Beijing+30) incorporó nuevos compromisos sobre violencia digital y brecha de IA.'),
('NM-037', 'Convenio 190 OIT — Eliminación de la Violencia y el Acoso en el Mundo del Trabajo', 'OIT — Organización Internacional del Trabajo', 'Convenio internacional', 'Internacional', 2019, 'Artículos 4, 7, 11 y 26', 'Los Estados ratificantes deben recopilar datos sobre violencia y acoso laboral con perspectiva de género. El artículo 11 obliga a producir estadísticas desagregadas por sexo sobre incidencia en el ámbito laboral.', 'Ag. Género · Ag. Datos', 'https://www.ilo.org/dyn/normlex/es/f?p=NORMLEXPUB:12100:0::NO::P12100_ILO_CODE:C190', 'Primer instrumento internacional vinculante sobre violencia y acoso laboral. Ratificado por Uruguay (2020), Argentina (2021), Ecuador (2021), México (2022) y Chile (2023) en ALC. Reconoce la violencia de género como forma específica de violencia laboral. La Recomendación 206 lo complementa.'),
('NM-038', 'Pacto Digital Mundial (Global Digital Compact) — ONU 2024', 'ONU / Asamblea General — Cumbre del Futuro', 'Declaración y marco de gobernanza digital', 'Internacional', 2024, 'Capítulo III — Inclusión digital · Principios sobre IA · Salvaguardas de género', 'Los Estados se comprometen a cerrar la brecha digital de género, garantizar que los sistemas de IA no perpetúen discriminación por género y promover la gobernanza de datos con perspectiva de género.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.un.org/techenvoy/es/global-digital-compact', 'Adoptado en septiembre de 2024 en la Cumbre del Futuro. Establece compromisos para una gobernanza digital inclusiva con perspectiva de género. Exige que los sistemas de IA estén libres de sesgos de género y que los datos representen de forma equitativa a mujeres y grupos marginalizados.'),
('NM-039', 'Recomendación General N.º 35 CEDAW (2017) — Violencia de Género contra la Mujer', 'Comité CEDAW — ONU', 'Recomendación general vinculante', 'Internacional', 2017, 'Párrafos 14, 29–31 (datos y estadísticas)', 'Los Estados deben reunir datos sistemáticos, comparables y de acceso público sobre violencia de género, incluyendo feminicidio, violencia sexual y violencia digital, desagregados por sexo, edad, etnia y relación con el agresor.', 'Ag. Género · Ag. Datos', 'https://www.ohchr.org/en/documents/treaty-specific-guidelines-and-references/cedaw-general-recommendation-no-35-2017', 'Actualiza y refuerza la Recomendación General 19 (1992) sobre violencia de género. Establece que la violencia de género es una forma de discriminación que incluye la violencia tecnológica/digital. Exige a los Estados datos estadísticos periódicos y comparables como obligación de debida diligencia.'),
('NM-040', 'Recomendación General N.º 40 CEDAW (2024) — Representación igualitaria en toma de decisiones', 'Comité CEDAW — ONU', 'Recomendación general vinculante', 'Internacional', 2024, 'Párrafos 40–45 (datos y seguimiento)', 'Los Estados deben recopilar y publicar datos desagregados por género sobre participación política y en cargos de toma de decisiones, incluyendo el sector tecnológico y de IA.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.ohchr.org/en/treaty-bodies/cedaw', 'Adoptada el 25 de octubre de 2024. Insta a los Estados a priorizar la paridad de género (50-50) como norma universal. Incluye por primera vez compromisos sobre representación femenina en el sector tecnológico y en la gobernanza de la IA. Resultado de un proceso de consultas regionales con ONU Mujeres y OHCHR.'),
('NM-041', 'Resolución ONU A/RES/78/217 — Cierre de la brecha digital de género (2023)', 'ONU / Asamblea General', 'Resolución de Asamblea General', 'Internacional', 2023, 'Párrafos operativos 5–12', 'Los Estados deben producir estadísticas desagregadas por género sobre acceso y uso de TIC, participación femenina en STEM e IA, y adoptar medidas para cerrar la brecha digital.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://undocs.org/A/RES/78/217', 'Resolución que exige a los Estados recopilar y difundir datos sobre la brecha digital de género. Reconoce que solo el 22,7% de graduadas en TIC son mujeres (OCDE 2024) y que las mujeres representan el 29% de la fuerza laboral STEM. Vincula estadísticas de género digital con el ODS 5.b.'),
('NM-042', 'Recomendación de la UNESCO sobre Ética de la IA (2021)', 'UNESCO — Organización de las Naciones Unidas para la Educación', 'Recomendación internacional no vinculante', 'Internacional', 2021, 'Artículos 42–48 (inclusión y equidad de género) · Artículo 53 (datos)', 'Los Estados deben garantizar que los sistemas de IA sean auditados para detectar sesgos de género, que los datos de entrenamiento sean representativos, y producir estadísticas sobre la participación de las mujeres en el desarrollo de IA.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://unesdoc.unesco.org/ark:/48223/pf0000381137_spa', 'Primer instrumento normativo global sobre ética de la IA. Adoptado por 193 Estados miembros en noviembre de 2021. Exige incorporar perspectiva de género en el diseño, desarrollo y despliegue de sistemas de IA. Establece que los sistemas de IA no deben perpetuar discriminación por género ni reproducir sesgos históricos.'),
('NM-043', 'Estrategia de Montevideo (2016) — Implementación de la Agenda Regional de Género', 'CEPAL — Conferencia Regional sobre la Mujer de ALC', 'Marco estratégico regional', 'ALyC', 2016, 'Ejes 1 (marcos normativos) · 3 (institucionalidad) · 6 (datos estadísticos) · 8 (tecnología)', 'Los Estados deben fortalecer los sistemas nacionales de estadística con perspectiva de género, producir datos sobre violencia feminicida, garantizar estadísticas desagregadas por sexo en encuestas de hogares e incorporar el enfoque de género en la producción de datos sobre TIC.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.cepal.org/es/publicaciones/41011-estrategia-montevideo-implementacion-agenda-regional-genero-marco-desarrollo', 'Marco estratégico adoptado en la XIII Conferencia Regional sobre la Mujer de ALC. Establece diez ejes de implementación para la Agenda Regional de Género. El eje 6 es específico sobre producción estadística con perspectiva de género. El eje 8 aborda tecnología, innovación y el cierre de la brecha digital de género.'),
('NM-044', 'Declaración de Santiago (2020) — Conferencia Regional sobre la Mujer de ALC', 'CEPAL — Conferencia Regional sobre la Mujer de ALC (XIV)', 'Declaración y compromisos regionales', 'ALyC', 2020, 'Párrafos 5, 19–22 (economía del cuidado · datos) · Párrafo 31 (tecnología y género)', 'Los Estados se comprometen a fortalecer los sistemas estadísticos con perspectiva de género, avanzar en la medición del trabajo no remunerado y de cuidados, y generar datos sobre la brecha digital de género.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://repositorio.cepal.org/bitstream/handle/11362/45611/S2000001_es.pdf', 'Adoptada en la XIV Conferencia Regional sobre la Mujer de ALC (Santiago, 2020). Incorpora compromisos sobre economía del cuidado y estadísticas de género. El párrafo 31 es específico sobre TIC y género. Antecede a los Compromisos de Tlatelolco (2025).'),
('NM-045', 'Compromisos de Tlatelolco (2025) — XVI Conferencia Regional sobre la Mujer de ALC', 'CEPAL — Conferencia Regional sobre la Mujer de ALC (XVI)', 'Declaración y compromisos regionales', 'ALyC', 2025, 'Compromisos 4 (datos) · 7 (tecnología) · 9 (violencia digital)', 'Los Estados se comprometen a cerrar brechas en estadísticas de género, garantizar datos sobre violencia digital y femicidio, y desarrollar marcos regulatorios de IA con perspectiva de género.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.cepal.org/es/eventos/xvi-conferencia-regional-mujer-america-latina-caribe', 'Adoptados en Ciudad de México en 2025, continuando la Agenda Regional de Género de la CEPAL. Son el marco regional más reciente para la igualdad de género en ALC. Incorporan explícitamente compromisos sobre inteligencia artificial, violencia digital contra mujeres, y producción estadística con perspectiva de género.'),
('NM-046', 'Guía para la Transversalización de la Perspectiva de Género en la Producción Estadística — CEA-CEPAL (2023)', 'CEPAL — Conferencia Estadística de las Américas (CEA)', 'Estándar regional estadístico', 'ALyC', 2023, 'Todos los capítulos — criterios para encuestas, censos, registros y difusión con perspectiva de género', 'Las Oficinas Nacionales de Estadística deben incorporar perspectiva de género en todas las fases de la producción estadística: diseño, recolección, procesamiento, análisis y difusión. Establece criterios para variables de identidad de género.', 'Ag. Género · Ag. Datos', 'https://www.cepal.org/es/publicaciones/48408-guia-transversalizacion-perspectiva-genero-produccion-estadistica', 'Adoptada como estándar regional en la XII Reunión de la CEA (2023). Desarrollada con aporte de INEGI, DANE, INE Chile, INEC Ecuador, INE Uruguay, IBGE e INDEC entre otras. Primer instrumento regional específico sobre estadísticas con perspectiva de género. Incluye criterios para medir identidad de género.'),
('NM-047', 'Ley Modelo MESECVI sobre Violencia Política contra las Mujeres (2017, actualizada 2024)', 'OEA / CIM — MESECVI', 'Ley modelo regional', 'ALyC', 2017, 'Artículos 3, 8, 14 (datos y registros)', 'Los Estados deben crear y mantener registros unificados sobre casos de violencia política contra las mujeres, con datos desagregados por tipo de violencia, nivel de gobierno y pertenencia étnica.', 'Ag. Género · Ag. Datos', 'https://www.oas.org/es/mesecvi/docs/LeyModeloViolenciaPolitica-ES.pdf', 'Herramienta normativa para que los países de ALC tipifiquen y sancionen la violencia política de género. Bolivia tiene la Ley 243 de referencia regional. La actualización 2024 incorpora violencia política digital. El MESECVI hace seguimiento de su implementación en los 32 Estados Parte de la Convención de Belém do Pará.'),
('NM-048', 'Declaración Iberoamericana de Datos Abiertos con Perspectiva de Género — SEGIB/ONU Mujeres (2025)', 'SEGIB · ONU Mujeres · OCDE — Foro Iberoamericano', 'Declaración política', 'Iberoamérica', 2025, 'Compromisos 1–5 (brecha digital) · Compromisos 6–8 (datos de género en IA)', 'Los gobiernos se comprometen a publicar datos abiertos con perspectiva de género sobre el sector tecnológico, incorporar métricas de género en los sistemas de gobernanza de IA y cerrar la brecha digital de género.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://lac.unwomen.org/es/stories/noticia/2025/03/onu-mujeres-segib-ocde-por-una-transicion-digital-inclusiva-en-iberoamerica', 'Adoptada en el marco de la CSW69 (Comisión de la Condición Jurídica y Social de la Mujer, marzo 2025). Copatrocinada por Costa Rica y Chile. Responde a la evidencia de que solo el 22,7% de graduadas en TIC son mujeres y el 29% de la fuerza laboral STEM es femenina. Primer marco iberoamericano específico sobre género y transición digital.'),
('NM-049', 'Ley 26.485 — Protección Integral para Prevenir, Sancionar y Erradicar la Violencia contra las Mujeres (Argentina)', 'Congreso de la Nación Argentina', 'Ley nacional integral', 'ARG', 2009, 'Artículos 4, 6, 11 (tipos y modalidades) · Artículo 37 (datos y registros)', 'El Estado argentino debe llevar un registro unificado de casos de violencia y producir estadísticas anuales sobre violencia contra las mujeres, desagregadas por tipo, modalidad y jurisdicción.', 'Ag. Género · Ag. Datos', 'https://www.argentina.gob.ar/normativa/nacional/ley-26485-152155', 'Ley integral de violencia de género que define tipos (física, psicológica, sexual, económica, simbólica, política) y modalidades (doméstica, institucional, laboral, mediática, obstétrica, digital). Modificada en 2019 por la Ley 27.501 (violencia política) y en 2023 por la Ley 27.736 (Ley Olimpia, violencia digital).'),
('NM-050', 'Ley 27.736 — Olimpia (Argentina): incorporación de violencia digital a Ley 26.485', 'Congreso de la Nación Argentina', 'Ley nacional de reforma', 'ARG', 2023, 'Modifica artículo 6 inc. i) de la Ley 26.485 — modalidad de violencia digital', 'El Estado debe registrar y producir estadísticas sobre violencia digital de género, incluyendo difusión no consentida de imágenes, doxing, acoso digital y ciberataques con perspectiva de género.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.mpd.gov.ar/index.php/noticias-h/ley-olimpia-una-nueva-herramienta-contra-la-violencia-de-genero', 'Sancionada el 11 de octubre de 2023. Incorpora la violencia digital como modalidad de violencia de género. Tipifica: difusión no consentida de imágenes íntimas, doxing, acoso y espionaje digital, accesos no autorizados. Permite ordenar a plataformas digitales la supresión de contenidos violentos. Inspirada en la Ley Olimpia de México.'),
('NM-051', 'Ley 27.499 — Ley Micaela (Argentina): capacitación obligatoria en género en el Estado', 'Congreso de la Nación Argentina', 'Ley nacional', 'ARG', 2019, 'Artículos 1–4 (alcance y obligatoriedad)', 'Todas las personas que integran los tres poderes del Estado deben capacitarse en perspectiva de género y violencia de género. El Estado debe producir datos sobre el alcance y resultados de las capacitaciones.', 'Ag. Género · Ag. Datos', 'https://www.argentina.gob.ar/normativa/nacional/ley-27499-318666', 'Establece la capacitación obligatoria en género para todo el sector público. Nombrada en honor a Micaela García, víctima de femicidio en 2017. Ha capacitado a más de 300.000 personas del sector público desde su implementación. Modelo replicado en varias provincias y países de la región.'),
('NM-052', 'Lei Maria da Penha — Lei N.º 11.340 (Brasil): mecanismos contra violencia doméstica', 'Congresso Nacional do Brasil', 'Ley nacional integral', 'BRA', 2006, 'Artigos 8, 26, 38 (estadísticas e información)', 'O Estado deve criar e manter sistema de dados e estatísticas sobre violência doméstica e familiar contra as mulheres, com desagregação por tipo de violência e perfil da vítima.', 'Ag. Género · Ag. Datos', 'https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11340.htm', 'Una de las leyes de violencia doméstica más reconocidas de América Latina. Establece mecanismos para prevenir, sancionar y erradicar la violencia doméstica y familiar contra las mujeres. Modificada en 2018 (Ley 13.772) para incorporar la violación de privacidad y grabación sexual sin consentimiento como formas de violencia doméstica.'),
('NM-053', 'Lei N.º 13.104 — Feminicídio (Brasil): tipificação do femicídio como homicídio qualificado', 'Congresso Nacional do Brasil', 'Ley nacional penal', 'BRA', 2015, 'Artigo 121, §2º-A (Código Penal) — razones de gênero', 'O Estado deve registrar e produzir estatísticas sobre feminicídios, desagregadas por perfil da vítima, vínculo com o agressor e circunstâncias do crime.', 'Ag. Género · Ag. Datos', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13104.htm', 'Tipifica el feminicidio como homicidio calificado. Brasil fue el 5.º país de ALC en incorporar este tipo penal. La ley exige la agravante cuando el crimen es cometido ''por razones de la condición de sexo femenino''. Base para las estadísticas oficiales del IBGE y del Ministerio de Justicia sobre feminicidios en Brasil.'),
('NM-054', 'Lei N.º 14.811 — Regulação de Plataformas Digitais e proteção de crianças/mulheres (Brasil, 2024)', 'Congresso Nacional do Brasil', 'Ley nacional digital', 'BRA', 2024, 'Artigos 15–25 (transparência de dados) · Artigos 30–35 (gênero e violência digital)', 'As plataformas digitais devem reportar dados sobre violência de gênero online ao Estado, incluindo denúncias por tipo de violência e perfil de vítimas e agressores.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', 'Ley brasileña de regulación de plataformas digitales con foco en protección de niños y mujeres. Exige a las plataformas reportes de transparencia sobre violencia de género digital. Inspirada en el Digital Services Act de la UE. Establece obligaciones de moderación de contenido y canales de denuncia para víctimas de violencia digital.'),
('NM-055', 'Ley General de Acceso de las Mujeres a una Vida Libre de Violencia — LGAMVLV (México, 2007 y reformas)', 'Congreso de la Unión de México', 'Ley nacional integral', 'MEX', 2007, 'Artículos 19–22 (BANAVIM) · Artículo 47 (datos y estadísticas) · Reforma 2021 (violencia digital)', 'El Estado debe mantener el Banco Nacional de Datos e Información sobre Casos de Violencia contra las Mujeres (BANAVIM). Las instituciones deben registrar y reportar datos estandarizados sobre violencia, incluyendo violencia digital.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LGAMVLV.pdf', 'Ley marco de violencia de género en México, reformada múltiples veces. La reforma de 2021 incorporó la violencia digital como modalidad específica (Ley Olimpia federal). Crea el BANAVIM y las Alertas de Violencia de Género contra las Mujeres (AVGM). Coordina a los tres órdenes de gobierno en materia de datos y atención.'),
('NM-056', 'Ley Olimpia Federal (México, 2021) — Reforma a LGAMVLV y Código Penal Federal', 'Congreso de la Unión de México', 'Reforma legislativa nacional', 'MEX', 2021, 'Art. 6 LGAMVLV (inc. k — violencia digital) · Art. 199 quinquies CPF (violación a la intimidad sexual)', 'El Estado debe registrar, investigar y producir estadísticas sobre violencia digital de género. La reforma establece el tipo penal autónomo de ''violación a la intimidad sexual'' con penas de 3 a 6 años.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://ordenjuridico.gob.mx/violenciagenero/LEY%20OLIMPIA.pdf', 'Reforma federal que consolida el marco jurídico de la Ley Olimpia. Tipifica la violencia digital como modalidad específica de violencia de género. Incorpora: difusión no consentida de imágenes íntimas, videos manipulados (deepfakes), captación sin consentimiento. Ha sido replicada en Argentina, Panamá y otros países de ALC.'),
('NM-057', 'NOM-046-SSA2-2005 — Violencia familiar, sexual y contra las mujeres: criterios estadísticos (México)', 'SESA / Secretaría de Salud de México', 'Norma Oficial Mexicana', 'MEX', 2009, 'Punto 5 (registro obligatorio) · Punto 8 (estadísticas del sector salud)', 'Las instituciones de salud deben registrar y reportar todos los casos de violencia familiar, sexual y contra las mujeres atendidos, con variables estandarizadas para producción estadística nacional.', 'Ag. Género · Ag. Datos', 'https://dof.gob.mx/nota_detalle.php?codigo=5087256&fecha=16/04/2009', 'Norma técnica que establece los criterios obligatorios de registro estadístico para casos de violencia atendidos en el sector salud. Es insumo del SIESVIM (INEGI). Fue la primera regulación técnica que exigió datos estandarizados sobre violencia de género en México. Referencia para el diseño del BANAVIM.'),
('NM-058', 'Ley 1761 — Rosa Elvira Cely (Colombia): tipificación del feminicidio como delito autónomo', 'Congreso de la República de Colombia', 'Ley nacional penal', 'COL', 2015, 'Artículos 1–7 (tipo penal) · Artículo 9 (estadísticas y seguimiento)', 'El Estado debe llevar estadísticas sobre feminicidios, feminicidios frustrados y violencias relacionadas, con seguimiento a la respuesta institucional y publicación anual de datos.', 'Ag. Género · Ag. Datos', 'https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=68197', 'Colombia fue el primer país de ALC en tipificar el feminicidio como delito autónomo (no como agravante del homicidio). Named after Rosa Elvira Cely, víctima de feminicidio en 2012. Crea obligaciones de seguimiento estadístico. Articulada con el SIVIGE del Ministerio de Salud para la producción de datos.'),
('NM-059', 'Ley 1257 de 2008 — Normas de sensibilización, prevención y sanción de la violencia y discriminación contra las mujeres (Colombia)', 'Congreso de la República de Colombia', 'Ley nacional integral', 'COL', 2008, 'Artículos 9 y 10 (medidas de sensibilización) · Artículo 9 (datos)', 'El Estado debe adoptar el Sistema Nacional de Estadísticas sobre Violencia basada en Género (SIVIGE) y recopilar datos desagregados sobre violencia contra las mujeres de múltiples fuentes institucionales.', 'Ag. Género · Ag. Datos', 'https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=34054', 'Ley marco de violencia de género en Colombia, antecede a la Ley 1761. Crea el mandato legal del SIVIGE, posteriormente implementado por el Ministerio de Salud con apoyo de ONU Mujeres y UNFPA. Define violencia psicológica, física, sexual y patrimonial. Obliga al Gobierno a producir estadísticas unificadas sobre violencia contra las mujeres.'),
('NM-060', 'Ley 21.212 — Tipifica el femicidio en Chile y amplía su alcance (Ley Gabriela)', 'Congreso Nacional de Chile', 'Ley nacional penal', 'CHL', 2020, 'Artículo 390 bis y ter del Código Penal — femicidio íntimo y no íntimo', 'El Estado debe registrar y producir estadísticas sobre femicidios consumados, frustrados y tentados, desagregadas por vínculo víctima-agresor, zona geográfica y perfil de víctima.', 'Ag. Género · Ag. Datos', 'https://www.bcn.cl/leychile/navegar?idNorma=1142338', 'Amplía la tipificación del femicidio más allá de la pareja o ex-pareja (femicidio no íntimo), conforme a la definición de la Declaración de Belém do Pará y la CEDAW. Chile registra 42 femicidios consumados en 2023 (CIF). Establece la base legal para el Informe Anual de Femicidio del Circuito Intersectorial.'),
('NM-061', 'Ley 21.675 — Estatuye medidas para prevenir, sancionar y erradicar la violencia de género (Chile, 2024)', 'Congreso Nacional de Chile', 'Ley nacional integral', 'CHL', 2024, 'Artículos 4–8 (tipos de violencia) · Artículo 25 (registro y datos)', 'El Estado debe crear y mantener registros integrados sobre violencia de género, con obligación de producir estadísticas anuales desagregadas por tipo de violencia, ámbito y perfil de víctima.', 'Ag. Género · Ag. Datos', 'https://www.bcn.cl/leychile/navegar?idNorma=1204862', 'Ley Integral de Violencia de Género aprobada en 2024. Crea la Comisión de Articulación Interinstitucional para Abordar la Violencia de Género. Abarca violencia física, psicológica, sexual, económica, simbólica, institucional, política y digital. Establece el Sistema de Registro de Asistencia a Víctimas (SRAV-Femicidio) como obligatorio.'),
('NM-062', 'Ley Orgánica Integral para la Prevención y Erradicación de la Violencia de Género contra las Mujeres — Ecuador (2018)', 'Asamblea Nacional de Ecuador', 'Ley nacional integral', 'ECU', 2018, 'Artículos 14–17 (Sistema Nacional Integral para la Prevención) · Artículo 32 (datos y registros)', 'El Estado debe crear el Sistema Nacional de Registro de Datos sobre violencia de género, con datos estandarizados de múltiples instituciones y publicación periódica de estadísticas.', 'Ag. Género · Ag. Datos', 'https://www.oas.org/es/mesecvi/docs/FinalReport-Ecuador-ES.pdf', 'Ley integral que tipifica la violencia en sus distintas formas y crea el Sistema Nacional Integral para la Prevención y Erradicación de la Violencia de Género. Ecuador tipificó el femicidio en 2014 (Código Orgánico Integral Penal). La ENVIGMU (INEC 2019) es el instrumento estadístico complementario más importante.'),
('NM-063', 'Reforma al COIP — Ecuador (2021): ciberbullying sexual y contenido íntimo sin consentimiento', 'Asamblea Nacional de Ecuador', 'Reforma penal nacional', 'ECU', 2021, 'Artículos nuevos al COIP — acoso digital, difusión no consentida de material íntimo', 'El Estado debe registrar y producir estadísticas sobre violencia digital de género, incluyendo acoso, ciberbullying sexual y difusión no consentida de imágenes.', 'Ag. Género · Ag. Datos · Ag. Tecnología', 'https://www.asambleanacional.gob.ec/', 'Ecuador reformó su Código Orgánico Integral Penal en 2021 para criminalizar el acoso digital, el ciberbullying sexual y la difusión no consentida de contenido íntimo, reconociéndolos como formas de violencia de género. Siguiendo el marco de la Ley Olimpia de México. El movimiento por la Ley Olimpia en Ecuador continuó movilizando activistas feministas.'),
('NM-064', 'Ley 19.580 — Violencia hacia las Mujeres basada en Género (Uruguay, 2017)', 'Parlamento de la República Oriental del Uruguay', 'Ley nacional integral', 'URY', 2017, 'Artículos 3–10 (tipos de violencia) · Artículo 44 (sistema de información) · Artículo 52 (datos)', 'El Estado debe crear el Sistema de Información Unificado sobre Violencia basada en Género con datos de todas las instituciones públicas. El Ministerio del Interior debe publicar datos anuales sobre violencia doméstica.', 'Ag. Género · Ag. Datos', 'https://www.impo.com.uy/bases/leyes/19580-2017', 'Ley integral de violencia de género más avanzada de Uruguay. Define 18 formas de violencia de género. Crea el Consejo Nacional para una Vida Libre de Violencia de Género. El Ministerio del Interior publica datos del SGSP (Sistema de Gestión de Seguridad Pública) en el catálogo de datos abiertos. Uruguay fue el primer país en ratificar el Convenio 190 OIT (2020).'),
('NM-065', 'Ley 30364 — Prevención, Sanción y Erradicación de la Violencia contra las Mujeres (Perú, 2015)', 'Congreso de la República del Perú', 'Ley nacional integral', 'PER', 2015, 'Artículos 4–11 (tipos de violencia) · Artículo 43 (Registro Único de Víctimas) · Artículo 44 (MIMP obligaciones de datos)', 'El Estado debe mantener el Registro Único de Víctimas de Violencia Familiar y Sexual y producir estadísticas anuales desagregadas por tipo de violencia, sexo, edad y ubicación geográfica.', 'Ag. Género · Ag. Datos', 'https://www.mimp.gob.pe/files/transparencia/leyes/ley-30364.pdf', 'Ley integral de violencia de género de Perú. Crea los Centros de Emergencia Mujer y el Registro Único de Víctimas. Establece el Plan Nacional contra la Violencia de Género 2016–2021. La ENDES (Encuesta Demográfica y de Salud Familiar del INEI) es el instrumento estadístico complementario. Perú tiene una de las tasas más altas de violencia de pareja en ALC.'),
('NM-066', 'Ley 348 — Ley Integral para Garantizar a las Mujeres una Vida Libre de Violencia (Bolivia, 2013)', 'Asamblea Legislativa Plurinacional de Bolivia', 'Ley nacional integral', 'BOL', 2013, 'Artículos 5–8 (tipos de violencia) · Artículos 71–76 (sistema de registro y estadísticas)', 'El Estado debe crear el Sistema Plurinacional de Información sobre violencia contra las mujeres, con datos de todas las instituciones intervinientes, desagregados por tipo de violencia, pueblo indígena y departamento.', 'Ag. Género · Ag. Datos', 'https://www.coordinadoradelamujer.org.bo/observatorio/index.php/normativas/ver/12', 'Ley marco de violencia de género en Bolivia. Crea el SIPPASE (Sistema de Información Plurinacional de Prevención, Atención, Sanción y Erradicación de la Violencia). Bolivia también tiene la Ley 243 sobre acoso y violencia política contra las mujeres (2012). La Coordinadora de la Mujer mantiene el Observatorio de Género con datos de la Ley 348.'),
('NM-067', 'Ley 5777 — Protección Integral a las Mujeres contra toda forma de Violencia (Paraguay, 2016)', 'Congreso de la República del Paraguay', 'Ley nacional integral', 'PRY', 2016, 'Artículos 3–9 (tipos de violencia) · Artículo 42 (sistema de información y datos)', 'El Estado debe crear el Sistema de Información sobre Violencia contra las Mujeres con datos de todas las instituciones, publicados con periodicidad anual.', 'Ag. Género · Ag. Datos', 'https://www.oas.org/es/mesecvi/docs/FinalReport-Paraguay-ES.pdf', 'Ley integral de violencia de género de Paraguay. Tipifica la violencia en sus distintas formas. Paraguay tipificó el feminicidio en 2016 (misma ley). Reporta al Observatorio de Igualdad de Género de CEPAL. El INE publica la EPHC con indicadores de género. Paraguay fue informante de la PARIS21 en la evaluación de estadísticas de género.'),
('NM-068', 'Ley 7586 — Ley contra la Violencia Doméstica (Costa Rica, 1996, con reformas)', 'Asamblea Legislativa de Costa Rica', 'Ley nacional', 'CRI', 1996, 'Artículos 2–4 (tipos de violencia) · Artículo 29 (estadísticas del Poder Judicial)', 'El Poder Judicial debe producir y publicar estadísticas anuales sobre casos de violencia doméstica y de género tramitados, desagregados por tipo de violencia, sexo y provincia.', 'Ag. Género · Ag. Datos', 'https://www.pgrweb.go.cr/scij/Busqueda/Normativa/Normas/nrm_texto_completo.aspx?param1=NRTC&nValor1=1&nValor2=34327', 'Ley base de violencia doméstica en Costa Rica, reformada múltiples veces. Costa Rica creó el SUMEVIG (Sistema Unificado de Medición Estadística de la Violencia de Género) para centralizar estadísticas de múltiples instituciones. Costa Rica reporta femicidios al OIG-CEPAL y tiene la ENAHO del INEC como fuente estadística principal.'),
('NM-069', 'Ley contra el Femicidio y otras formas de Violencia contra la Mujer — Decreto 22-2008 (Guatemala)', 'Congreso de la República de Guatemala', 'Ley nacional penal e integral', 'GTM', 2008, 'Artículos 3–6 (tipos de violencia y femicidio) · Artículo 22 (sistema de información)', 'El Estado debe llevar registros estadísticos sobre femicidios y violencia contra las mujeres, con datos desagregados por tipo de violencia y etnia.', 'Ag. Género · Ag. Datos', 'https://www.oas.org/es/mesecvi/docs/FinalReport-Guatemala-ES.pdf', 'Ley pionera en la región que tipifica el femicidio con perspectiva de género amplia. Guatemala registra la segunda tasa de femicidios más alta de ALC (1,9 por 100.000 mujeres en 2024, CEPAL). La dimensión étnica es crítica: incluye desagregación por pertenencia a pueblos indígenas. Articulada con la Ley Marco de los Acuerdos de Paz.');
INSERT INTO metodologia_senales (senal, descripcion, notas) VALUES
('S1 Metadatos (20%)', 'Fuente identificada + metodología documentada. Sola no determina calidad completa.', 'Completa requiere las 4 señales'),
('S2 Frecuencia (30%)', 'Más de 3 años sin actualizar = Nula (bloquea). Más de 2 años = Parcial. Menos de 2 años = OK.', 'Umbral 3 años bloquea'),
('S3 Desagregación (30%)', 'Distribución geográfica (municipio/región/territorio) = 100%. Solo totales nacionales = 30%. Sin info = 0%.', 'Clave para brechas territoriales'),
('S4 Accesibilidad (20%)', 'URL activa + formato legible por máquina (CSV/JSON/XLSX/API) = 100%. PDF no legible = 25%. Sin descarga = 10%.', 'API > CSV > XLSX > PDF');
INSERT INTO metodologia_clasificacion (clasificacion, criterio, requisito) VALUES
('Clasificación', 'Criterio', 'Requisito'),
('Completa', 'Score ≥ 0.70 + frecuencia ≤ 2 años + desagregación geográfica + formato legible', 'Requiere las 4 condiciones'),
('Parcial', 'Score entre 0.35 y 0.69, o alguna condición de Completa no cumplida', 'La más frecuente'),
('Nula', 'Score < 0.35, o dato inexistente, o antigüedad > 3 años (bloqueo)', 'Bloqueo automático por frecuencia');
INSERT INTO metodologia_agendas (agenda, marco_referencia, nota) VALUES
('Agenda', 'Marco de referencia', 'Nota'),
('Agenda Tecnológica', 'DGDF-UNDP · UIT/ITU · GDC 2024. Brecha digital de género, IA, TICs y violencia digital.', 'Un dataset puede estar en varias agendas'),
('Agenda de Datos', 'UN NQAF · CEPAL · HRBA to Data · Marco de Copenhague. Calidad estadística, gobernanza de datos.', 'Un dataset puede estar en varias agendas'),
('Agenda de Género', 'Paris21 · MESECVI · CEDAW · Belém do Pará. Violencia, salud reproductiva, autonomía, interseccionalidad.', 'Un dataset puede estar en varias agendas');
INSERT INTO metodologia_vacios (codigo, descripcion, paises_afectados) VALUES
('V-01: Violencia digital sin datos abiertos', 'Ningún país tiene un dataset gubernamental específico de violencia digital de género (pornovenganza, deepfakes, ciberacoso). La ENDIREH 2021 (MEX) es la única encuesta con módulo digital.', 'MEX · ECU · ARG'),
('V-02: Ecuador sin encuesta de violencia actualizada', 'La ENVIGMU fue en 2019 y no incluyó módulo digital. No hay encuesta nacional de violencia de género posterior. Vacío estadístico de 6+ años.', 'ECU'),
('V-03: Línea 144 ARG discontinuada', 'La Línea 144 dejó de publicar datos en julio 2023 tras la disolución del MMGyD. No hay sustituto con apertura comparable.', 'ARG'),
('V-04: IA sin regulación con perspectiva de género', 'Ninguno de los tres países tiene ley de IA aprobada. Los proyectos de ECU y MEX no tienen enfoque de género. Los deepfakes solo se persiguen vía Ley Olimpia (MEX) o de forma indirecta.', 'MEX · ECU · ARG'),
('V-05: Brecha digital sin desagregación subnacional completa', 'ARCOTEL (ECU) y ENACOM (ARG) no publican datos de acceso a internet desagregados por sexo a nivel provincial. Solo ENDUTIH (MEX) y ENEMDU (ECU) tienen este nivel.', 'ECU · ARG');
INSERT INTO metodologia_score_brecha (elemento, descripcion, valor) VALUES
('Fórmula', 'score = (1 - similitud_dataset) × 0.6 + cobertura_normativa × 0.4', 'Resultado entre 0 y 1'),
('Brecha Crítica', 'Score ≥ 0.70 — dato ausente o insuficiente frente a normativa', NULL),
('Brecha Parcial', 'Score 0.40–0.69 — dato existe con limitaciones significativas', NULL),
('Brecha Cubierta', 'Score < 0.40 — dato disponible y de calidad aceptable', NULL);
